part of'purchases_screens.dart';class ExpiryScreen extends ConsumerStatefulWidget{const ExpiryScreen({super.key});@override ConsumerState<ExpiryScreen>createState()=>_ExpiryScreenState();}class _ExpiryScreenState extends ConsumerState<ExpiryScreen>{String _tab='soon';@override Widget build(BuildContext context){final d=ref.watch(pharmacyProvider).value;final can=ref.watch(permissionsProvider).value??const<String>{};final session=ref.watch(sessionControllerProvider).value;if(d==null)return const Center(child:CircularProgressIndicator());final st=d.settings;final warn=st.expiryWarnDays.round();final e=expiryBatches(d.products.where((p)=>d.stockOf(p.id)>0),d.stock.batchesOf,d.stockOf,warn);final rows=_tab=='expired'?e.expired:e.soon;double worth((Product,BatchStock,int)x)=>x.$2.qty*(x.$2.cost!=0?x.$2.cost:x.$1.cost);final value=rows.fold(0.0,(a,x)=>a+worth(x));final title=_tab=='expired'?'Expired stock':'Expiring within $warn days';return PageFrame(title:'Expiring / Expired',subtitle:'${rows.length} batches · ${st.money(value)} at cost',actions:[ExportButtons(name:_tab=='expired'?'expired-stock':'expiring-stock',settings:st,title:title,subtitle:'${rows.length} batches in stock · ${st.money(value)} at cost',pdf:()=>[PdfTable(head:const['Medicine','Batch','Expiry','When','Qty','Value'],numeric:const[4,5],body:[for(final(p,b,days)in rows)[p.name,b.batch,b.expiry,days<0?'${-days} days ago':days==0?'today':'in $days days',formatQty(b.qty),st.money(b.qty*(b.cost!=0?b.cost:p.cost))],]),],),],child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Align(alignment:Alignment.centerLeft,child:SegmentedButton<String>(segments:[ButtonSegment(value:'soon',label:Text('Expiring within $warn days (${e.soon.length})')),ButtonSegment(value:'expired',label:Text('Expired (${e.expired.length})'))],selected:{_tab},onSelectionChanged:(v)=>setState(()=>_tab=v.first),),),const SizedBox(height:8),Expanded(child:rows.isEmpty?EmptyState(_tab=='expired'?'No expired stock 🎉':'Nothing expiring soon 🎉'):ListView.separated(itemCount:rows.length,separatorBuilder:(_,_)=>const Divider(height:1),itemBuilder:(_,i){final(p,b,days)=rows[i];return ListTile(title:Text(p.name),subtitle:Text('batch ${b.batch} · ${formatQty(b.qty)} in stock · ${st.money(b.qty * (b.cost != 0 ? b.cost : p.cost))} · expires ${b.expiry} (${days < 0 ? '${-days}days ago' : days == 0 ? 'today' : 'in $days days'})'),leading:Icon(days<0?Icons.error_outline:Icons.schedule,color:days<0?Theme.of(context).colorScheme.error:Colors.orange.shade800),trailing:Wrap(spacing:4,children:[if(can.contains('stock.receive')||can.contains('stock.adjust'))TextButton(onPressed:()=>returnDialog(context,ref,p,b,days<0?'Expired':'Short expiry'),child:const Text('Return')),if(_tab=='expired'&&session?.role!='cashier')TextButton(style:TextButton.styleFrom(foregroundColor:Theme.of(context).colorScheme.error),onPressed:()async{if(!await confirmAction(context,'Write off expired stock?','${formatQty(b.qty)} × ${p.name} (batch ${b.batch}) will be removed from stock.','Write off'))return;await writeOffBatch(ref.read(recordStoreProvider),p,b,settings:st,user:session?.userName??'',branchId:d.branch);if(context.mounted)say(context,'${p.name} batch ${b.batch} written off');},child:const Text('Write off'),),]),);},),),]),);}}